			long nextMaximum = Math.max(maximum, weights[start - 1]);
			long maximumAllowed = nextMinimum > Long.MAX_VALUE / MAX_WEIGHT_SKEW ? Long.MAX_VALUE
					: nextMinimum * MAX_WEIGHT_SKEW;
			if (nextMaximum > maximumAllowed) {
				break;
			}
			minimum = nextMinimum;
			maximum = nextMaximum;
			start--;
